fun E() { T(); Elinha() }
fun Elinha() {
 if (look == "+") { match("+"); T(); Elinha() }
 // senão: ε (look deve estar em FOLLOW(E') = { ), $ })
}
fun T() { F(); Tlinha() }
fun Tlinha() {
 if (look == "*") { match("*"); F(); Tlinha() }
}
fun F() {
 when (look) {
 "(" -> { match("("); E(); match(")") }
 "id" -> match("id")
 else -> erro("esperava ( ou id")
 }
}

fun D() { T(); L(); match(";") } // produção única

fun T() {
 when (look) {
 "int" -> match("int")
 "float" -> match("float")
 else -> erro("esperava um tipo")
 }
}

fun L() { match("id"); R() } // L → id R

